INSERT INTO enfermedades (nombre, categoria, descripcion, recomendacionGeneral, gravedad) VALUES
('Sobrepeso', 'Control de peso', 'Condición en la que el perro tiene más peso del recomendado para su tamaño, edad y raza.', 'Controlar porciones, reducir premios y ajustar calorías diarias.', 'media'),

('Obesidad', 'Control de peso', 'Acumulación excesiva de grasa corporal que puede afectar la movilidad, respiración y salud general del perro.', 'Usar una dieta de control de peso y consultar al veterinario para calcular calorías.', 'alta'),

('Diabetes mellitus', 'Control de peso', 'Enfermedad metabólica donde el cuerpo no regula correctamente la glucosa en sangre.', 'Mantener horarios fijos de comida y dieta controlada bajo indicación veterinaria.', 'alta'),

('Desnutrición', 'Crecimiento y deficiencias', 'Estado causado por falta de nutrientes, calorías, proteínas, vitaminas o minerales necesarios.', 'Usar alimento completo y balanceado según edad y condición corporal.', 'alta'),

('Pancreatitis', 'Digestiva', 'Inflamación del páncreas que puede provocar dolor abdominal, vómitos, diarrea y pérdida de apetito.', 'Evitar alimentos altos en grasa y consultar dieta baja en grasa con veterinario.', 'alta'),

('Gastritis', 'Digestiva', 'Inflamación del estómago que puede causar vómito, náuseas, dolor abdominal o falta de apetito.', 'Evitar cambios repentinos de comida y alimentos condimentados.', 'media'),

('Colitis', 'Digestiva', 'Inflamación del colon que puede causar diarrea, molestias intestinales y evacuaciones frecuentes.', 'Mantener dieta estable y revisar ingredientes que puedan causar irritación intestinal.', 'media'),

('Diarrea crónica', 'Digestiva', 'Problema digestivo persistente caracterizado por evacuaciones blandas o líquidas durante varios días o de forma recurrente.', 'Identificar ingredientes problemáticos y evitar cambios rápidos de croqueta.', 'media'),

('Estreñimiento', 'Digestiva', 'Dificultad para evacuar que puede estar relacionada con poca fibra, baja hidratación o poca actividad física.', 'Aumentar hidratación y revisar el aporte de fibra en la dieta.', 'baja'),

('Flatulencias excesivas', 'Digestiva', 'Producción frecuente de gases intestinales, generalmente asociada a intolerancias, cambios de alimento o mala digestión.', 'Revisar ingredientes, cambiar alimento gradualmente y evitar comidas pesadas.', 'baja'),

('Alergia alimentaria', 'Alergias y piel', 'Reacción del sistema inmune ante ciertos ingredientes del alimento, especialmente algunas proteínas.', 'Usar dieta de eliminación o alimento hipoalergénico bajo supervisión veterinaria.', 'media'),

('Intolerancia alimentaria', 'Alergias y piel', 'Dificultad para digerir ciertos ingredientes, sin necesariamente involucrar una reacción alérgica.', 'Evitar ingredientes que causen vómito, diarrea, gases o malestar.', 'media'),

('Dermatitis por alergia alimentaria', 'Alergias y piel', 'Irritación o inflamación de la piel relacionada con una reacción adversa a ciertos alimentos.', 'Revisar si la comezón o irritación coincide con ciertos alimentos.', 'media'),

('Otitis recurrente asociada a alergias', 'Alergias y piel', 'Infecciones o inflamaciones repetidas del oído que pueden estar relacionadas con alergias alimentarias.', 'Consultar si las infecciones de oído se repiten junto con síntomas de alergia.', 'media');